/**
 * System alerts in the unified review queue.
 *
 * A PunchEvidenceReview is generated by the attendance validation engine. It is
 * reviewed (Mark Reviewed / Dismiss), never approved, never shown as raised by
 * the employee it is about, and never mixed into the default request list.
 */
import { BadRequestException, ForbiddenException } from '@nestjs/common';
import { ReviewQueueService } from '../../src/modules/platform/review-queue/review-queue.service';
import { PunchReviewService } from '../../src/modules/platform/attendance/console/punch-review.service';
import { alertReasons, alertTitle, groupSystemAlerts } from '../../src/modules/platform/review-queue/system-alerts';

const DATE = '2026-10-29';
const person = (id: string, name: string, extra: Record<string, unknown> = {}) => ({
  id, employeeId: `TE-${id}`, name, avatar: null, photoUrl: null, designation: null,
  role: { name: 'EMPLOYEE' }, department: { id: 'd-ops', name: 'Operations' }, ...extra,
});
const VIVEK = person('vivek', 'Vivek Mehta');
const ASHA = person('asha', 'Asha Rao');
const RAVI = person('ravi', 'Ravi Kumar');

const ACTORS: Record<string, any> = {
  hr: { id: 'hr', name: 'HR User', employeeId: 'TE-HR', isHR: true, role: { name: 'MANAGER', level: 2 }, department: null },
  admin: { id: 'admin', name: 'Admin', employeeId: 'TE-AD', isHR: false, role: { name: 'ADMIN', level: 1 }, department: null },
  super: { id: 'super', name: 'Super', employeeId: 'TE-SU', isHR: false, role: { name: 'SUPER_ADMIN', level: 0 }, department: null },
  manager: { id: 'manager', name: 'Manager', employeeId: 'TE-MG', isHR: false, role: { name: 'MANAGER', level: 2 }, department: null },
  employee: { id: 'employee', name: 'Employee', employeeId: 'TE-EM', isHR: false, role: { name: 'EMPLOYEE', level: 4 }, department: null },
};

type Review = { id: string; evidenceId: string; reasonCodes: string[]; status: string; createdAt: Date; note?: string | null; reviewedById?: string | null; reviewedAt?: Date | null; evidence: any };

function review(id: string, who: any, type: 'PUNCH_IN' | 'PUNCH_OUT', hhmm: string, reasonCodes: string[], status = 'PENDING', date = DATE): Review {
  const at = new Date(`${date}T${hhmm}:00.000Z`);
  return {
    id, evidenceId: `ev-${id}`, reasonCodes, status, createdAt: at,
    evidence: {
      id: `ev-${id}`, userId: who.id, user: who, type, businessDate: new Date(`${date}T00:00:00.000Z`),
      serverOccurredAt: at, deviceType: 'DESKTOP', captureChannel: 'CURRENT_DEVICE',
    },
  };
}

/**
 * An in-memory Prisma double. Only the review rows and assignments may be
 * written; any other write is recorded so a test can prove nothing else moved.
 */
function rig(reviews: Review[], opts: { corrections?: any[]; leaves?: any[] } = {}) {
  const forbiddenWrites: string[] = [];
  const guard = (model: string) => new Proxy({}, {
    get: (_t, method: string) => () => {
      if (/create|update|delete|upsert/i.test(method)) forbiddenWrites.push(`${model}.${method}`);
      return Promise.resolve(method === 'findMany' ? [] : null);
    },
  });
  const corrections = opts.corrections ?? [];
  const leaves = opts.leaves ?? [];
  const matches = (row: Review, where: any = {}) => {
    if (where.id && typeof where.id === 'string' && row.id !== where.id) return false;
    if (where.id?.not && row.id === where.id.not) return false;
    if (typeof where.status === 'string' && row.status !== where.status) return false;
    if (where.status?.in && !where.status.in.includes(row.status)) return false;
    if (where.evidence?.userId && row.evidence.userId !== where.evidence.userId) return false;
    if (where.evidence?.businessDate && row.evidence.businessDate.getTime() !== where.evidence.businessDate.getTime()) return false;
    return true;
  };
  const prisma: any = {
    attendanceRegularization: { findMany: jest.fn().mockResolvedValue(corrections) },
    leaveRequest: { findMany: jest.fn().mockResolvedValue(leaves) },
    departmentTransfer: { findMany: jest.fn().mockResolvedValue([]) },
    retentionRuleProposal: { findMany: jest.fn().mockResolvedValue([]) },
    userLegalHold: { findMany: jest.fn().mockResolvedValue([]) },
    fnfAdjustmentRequest: { findMany: jest.fn().mockResolvedValue([]) },
    dailyAttendance: guard('dailyAttendance'),
    attendancePunchEvidence: guard('attendancePunchEvidence'),
    payrollRun: guard('payrollRun'),
    leaveBalance: guard('leaveBalance'),
    user: {
      findUnique: jest.fn(async ({ where }: any) => ACTORS[where.id] ?? null),
      findMany: jest.fn().mockResolvedValue([]),
    },
    reviewQueueAssignment: {
      findMany: jest.fn().mockResolvedValue([]),
      findFirst: jest.fn().mockResolvedValue(null),
      updateMany: jest.fn().mockResolvedValue({ count: 0 }),
    },
    punchEvidenceReview: {
      findMany: jest.fn(async ({ where }: any) => reviews.filter((r) => matches(r, where)).map((r) => ({ ...r }))),
      findUnique: jest.fn(async ({ where }: any) => reviews.find((r) => r.id === where.id) ?? null),
      updateMany: jest.fn(async ({ where, data }: any) => {
        const row = reviews.find((r) => matches(r, where));
        if (!row) return { count: 0 };
        Object.assign(row, data);
        return { count: 1 };
      }),
    },
  };
  // Corrections and leave: the subject's manager reviews on the team tab, HR on company.
  const authority = {
    loadActor: async (id: string) => ACTORS[id],
    eligibility: async (actor: any) => (actor.isHR || ['ADMIN', 'SUPER_ADMIN'].includes(actor.role?.name)
      ? { scope: 'company' }
      : actor.id === 'manager' ? { scope: 'team' } : null),
  };
  const events = { log: jest.fn().mockResolvedValue(undefined) };
  const access = { isHrOrAdmin: (a: any) => !!a && (a.isHR || ['ADMIN', 'SUPER_ADMIN'].includes(a.role?.name)) };
  const punchReviews = new PunchReviewService(prisma, { now: () => new Date('2026-10-30T06:00:00.000Z') } as any, access as any, events as any);
  const service = new ReviewQueueService(
    prisma, authority as any, {} as any, {} as any, {} as any, punchReviews,
    {} as any, {} as any, {} as any, { log: jest.fn().mockResolvedValue(undefined) } as any,
  );
  return { service, prisma, events, reviews, forbiddenWrites };
}

const correction = (id: string, who: any) => ({
  id, userId: who.id, user: who, reason: 'Forgot to punch out', createdAt: new Date(`${DATE}T12:00:00.000Z`), status: 'PENDING',
  date: new Date(`${DATE}T00:00:00.000Z`), requestType: 'MISSING_PUNCH', requestedPunchIn: null, requestedPunchOut: null, createdById: who.id,
});
const leave = (id: string, who: any) => ({
  id, userId: who.id, user: who, reason: 'Family function', createdAt: new Date(`${DATE}T11:00:00.000Z`), status: 'PENDING',
  type: 'CASUAL', startDate: new Date('2026-11-02T00:00:00.000Z'), endDate: new Date('2026-11-02T00:00:00.000Z'), isHalfDay: false,
});

function standardRig() {
  return rig(
    [
      review('pr-1', VIVEK, 'PUNCH_IN', '04:00', ['POLICY_SETUP_PENDING', 'POLICY_BLOCKER:MISSING_SHIFT_ASSIGNMENT']),
      review('pr-2', VIVEK, 'PUNCH_OUT', '13:00', ['POLICY_SETUP_PENDING', 'DEVICE_ID_UNAVAILABLE']),
      review('pr-3', ASHA, 'PUNCH_IN', '04:30', ['ACCURACY_UNAVAILABLE']),
      // Historical row: written before the blocker prefix existed.
      review('pr-old', RAVI, 'PUNCH_IN', '03:30', ['POLICY_SETUP_PENDING'], 'PENDING', '2026-08-14'),
      review('pr-done', RAVI, 'PUNCH_OUT', '12:00', ['DEVICE_ID_UNAVAILABLE'], 'REVIEWED', '2026-08-14'),
    ],
    { corrections: [correction('c-1', ASHA)], leaves: [leave('l-1', RAVI)] },
  );
}

describe('Review queue system alerts', () => {
  describe('contract', () => {
    it('1-3. a punch evidence review is SYSTEM, has no requester, and the employee is only the affected employee', async () => {
      const { service } = standardRig();
      const { items } = await service.list({ id: 'hr' }, 'company', 'system');
      const alert = items.find((i) => i.affectedEmployee?.id === 'asha')!;
      expect(alert).toMatchObject({
        origin: 'SYSTEM',
        generatedBy: 'ATTENDANCE_VALIDATION_ENGINE',
        requester: null,
        employee: null,
        affectedEmployee: { id: 'asha', employeeId: 'TE-asha', name: 'Asha Rao', department: 'Operations' },
        requiresApproval: false,
        reviewActions: ['MARK_REVIEWED', 'DISMISS'],
        requestTypeLabel: 'Punch Evidence Alert',
      });
    });

    it('10. existing employee requests keep their shape and gain a USER origin', async () => {
      const { service } = standardRig();
      const { items } = await service.list({ id: 'hr' }, 'company');
      const fix = items.find((i) => i.id === 'c-1')!;
      expect(fix).toMatchObject({
        origin: 'USER', generatedBy: null, requiresApproval: true, reviewActions: ['APPROVE', 'REJECT'],
        requestTypeLabel: 'Attendance Correction', reason: 'Forgot to punch out', status: 'PENDING',
        employee: expect.objectContaining({ id: 'asha', name: 'Asha Rao' }),
        requester: { id: 'asha', employeeId: 'TE-asha', name: 'Asha Rao', department: 'Operations' },
      });
      expect(items.find((i) => i.id === 'l-1')).toMatchObject({ requestType: 'LEAVE_REQUEST', origin: 'USER' });
    });
  });

  describe('filtering', () => {
    it('4-5. the default list (All request types) never includes system alerts', async () => {
      const { service } = standardRig();
      for (const scope of ['company', 'team'] as const) {
        const { items } = await service.list({ id: 'hr' }, scope);
        expect(items.some((i) => i.origin === 'SYSTEM' || i.requestType === 'PUNCH_EVIDENCE_REVIEW')).toBe(false);
      }
    });

    it('7. default totals and counts exclude system alerts', async () => {
      const { service } = standardRig();
      const list = await service.list({ id: 'hr' }, 'company');
      expect(list.total).toBe(2);
      expect(list.items.map((i) => i.id).sort()).toEqual(['c-1', 'l-1']);
      const counts = await service.counts({ id: 'hr' });
      expect(counts.company).toBe(2);
      expect(counts.team).toBe(0);
    });

    it('6, 8. the system filter returns only system alerts, with its own total and count', async () => {
      const { service } = standardRig();
      const list = await service.list({ id: 'hr' }, 'company', 'system');
      expect(list.items.every((i) => i.origin === 'SYSTEM')).toBe(true);
      // Vivek's two alerts on one date are one row; Ravi's reviewed one stays separate.
      expect(list.total).toBe(4);
      expect(list.items).toHaveLength(4);
      const counts = await service.counts({ id: 'hr' });
      expect(counts.system).toBe(3);
    });

    it('9. a name search under the system filter matches the affected employee', async () => {
      const { service } = standardRig();
      const { items } = await service.list({ id: 'hr' }, 'company', 'system');
      // The client searches the same field the table shows.
      const hit = items.filter((i) => (i.affectedEmployee?.name ?? '').toLowerCase().includes('vivek'));
      expect(hit).toHaveLength(1);
      expect(hit[0].affectedEmployee!.name).toBe('Vivek Mehta');
    });

    it('18. historical rows with no recorded blocker appear under the system filter', async () => {
      const { service } = standardRig();
      const { items } = await service.list({ id: 'hr' }, 'company', 'system');
      const old = items.find((i) => i.id === 'pr-old')!;
      expect(old).toMatchObject({ origin: 'SYSTEM', requester: null, status: 'PENDING', reason: 'Attendance policy setup pending' });
      expect((old.details.alertReasons as any[])[0].explanation).toMatch(/exact blocker .* unavailable/i);
      const done = items.find((i) => i.id === 'pr-done')!;
      expect(done).toMatchObject({ origin: 'SYSTEM', sourceStatus: 'REVIEWED', status: 'APPROVED' });
    });
  });

  describe('reasons and grouping', () => {
    it('19. evidence flags read as HR-facing explanations', () => {
      const [policy, device, gps] = alertReasons(['POLICY_SETUP_PENDING', 'POLICY_BLOCKER:MISSING_SHIFT_ASSIGNMENT', 'POLICY_BLOCKER:AMBIGUOUS_HOLIDAY_CALENDAR', 'DEVICE_ID_UNAVAILABLE', 'ACCURACY_UNAVAILABLE']);
      expect(policy.title).toBe('Attendance policy setup pending');
      expect(policy.explanation).toContain('No shift is assigned');
      expect(policy.explanation).toContain('ambiguous calendar assignment');
      expect(device).toMatchObject({ title: 'Device ID unavailable', explanation: expect.stringMatching(/installation ID was unavailable or invalid/) });
      expect(gps).toMatchObject({ title: 'GPS accuracy unavailable', explanation: expect.stringMatching(/GPS accuracy/) });
      const generic = alertReasons(['POLICY_SETUP_PENDING'])[0];
      expect(generic.blockers).toEqual([]);
      expect(generic.explanation).toMatch(/exact blocker was not recorded/);
      expect(alertTitle(['POLICY_BLOCKER:MISSING_SHIFT_ASSIGNMENT', 'POLICY_SETUP_PENDING'])).toBe('Attendance policy setup pending');
    });

    it('20. repeated alerts for one employee and date group into one row without losing a source record', async () => {
      const { service, reviews } = standardRig();
      const { items } = await service.list({ id: 'hr' }, 'company', 'system');
      const vivek = items.filter((i) => i.affectedEmployee?.id === 'vivek');
      expect(vivek).toHaveLength(1);
      expect(vivek[0].details).toMatchObject({
        businessDate: DATE,
        evidenceCount: 2,
        reviewIds: ['pr-1', 'pr-2'],
        punchType: ['PUNCH_IN', 'PUNCH_OUT'],
        reasonCodes: ['POLICY_SETUP_PENDING', 'POLICY_BLOCKER:MISSING_SHIFT_ASSIGNMENT', 'DEVICE_ID_UNAVAILABLE'],
      });
      expect((vivek[0].details.punchEvents as any[]).map((e) => e.reviewId)).toEqual(['pr-1', 'pr-2']);
      expect(vivek[0].reason).toBe('Attendance policy setup pending · Device ID unavailable');
      expect(reviews).toHaveLength(5);
    });

    it('groups only within the same status', () => {
      const base: any = { origin: 'SYSTEM', affectedEmployee: { id: 'x' }, subjectUserId: 'x', requestDate: '2026-10-29T01:00:00.000Z' };
      const grouped = groupSystemAlerts([
        { ...base, id: 'a', sourceStatus: 'PENDING', details: { businessDate: DATE, reasonCodes: ['ACCURACY_UNAVAILABLE'] } },
        { ...base, id: 'b', sourceStatus: 'REVIEWED', details: { businessDate: DATE, reasonCodes: ['ACCURACY_UNAVAILABLE'] } },
      ]);
      expect(grouped).toHaveLength(2);
    });
  });

  describe('actions', () => {
    it('13, 15. Mark Reviewed sets REVIEWED on every pending member, records the reviewer, and audits each', async () => {
      const { service, reviews, events } = standardRig();
      const result: any = await service.decide({ id: 'hr', isHR: true }, 'PUNCH_EVIDENCE_REVIEW', 'pr-2', { action: 'MARK_REVIEWED' });
      expect(result).toMatchObject({ action: 'MARK_REVIEWED', status: 'REVIEWED', reviewIds: ['pr-2', 'pr-1'] });
      for (const id of ['pr-1', 'pr-2']) {
        const row = reviews.find((r) => r.id === id)!;
        expect(row).toMatchObject({ status: 'REVIEWED', reviewedById: 'hr', reviewedAt: new Date('2026-10-30T06:00:00.000Z') });
      }
      expect(reviews.find((r) => r.id === 'pr-3')!.status).toBe('PENDING');
      expect(events.log).toHaveBeenCalledTimes(2);
      expect(events.log).toHaveBeenCalledWith(expect.objectContaining({
        actorId: 'hr', entityType: 'PunchEvidenceReview', entityId: 'pr-1',
        action: 'ATTENDANCE_PUNCH_REVIEWED', fromState: 'PENDING', toState: 'REVIEWED',
      }));
    });

    it('14, 15. Dismiss requires a reason, then sets DISMISSED and audits the reason', async () => {
      const { service, reviews, events } = standardRig();
      await expect(service.decide({ id: 'hr', isHR: true }, 'PUNCH_EVIDENCE_REVIEW', 'pr-3', { action: 'DISMISS' }))
        .rejects.toThrow('A reason is required to dismiss a system alert');
      await expect(service.decide({ id: 'hr', isHR: true }, 'PUNCH_EVIDENCE_REVIEW', 'pr-3', { action: 'DISMISS', reason: '   ' }))
        .rejects.toBeInstanceOf(BadRequestException);
      expect(reviews.find((r) => r.id === 'pr-3')!.status).toBe('PENDING');

      await service.decide({ id: 'hr', isHR: true }, 'PUNCH_EVIDENCE_REVIEW', 'pr-3', { action: 'DISMISS', reason: 'Known GPS issue on this laptop' });
      expect(reviews.find((r) => r.id === 'pr-3')).toMatchObject({ status: 'DISMISSED', reviewedById: 'hr', note: 'Known GPS issue on this laptop' });
      expect(events.log).toHaveBeenCalledWith(expect.objectContaining({
        entityId: 'pr-3', toState: 'DISMISSED', metadata: expect.objectContaining({ note: 'Known GPS issue on this laptop' }),
      }));
    });

    it('a system alert cannot be approved, rejected or transferred', async () => {
      const { service, reviews } = standardRig();
      for (const decision of ['APPROVE', 'REJECT']) {
        await expect(service.decide({ id: 'hr', isHR: true }, 'PUNCH_EVIDENCE_REVIEW', 'pr-3', { decision, reason: 'x' }))
          .rejects.toThrow('not approved or rejected');
      }
      await expect(service.forward({ id: 'hr' }, 'PUNCH_EVIDENCE_REVIEW', 'pr-3', { reviewerId: 'admin' })).rejects.toBeInstanceOf(BadRequestException);
      await expect(service.forwardCandidates({ id: 'hr' }, 'PUNCH_EVIDENCE_REVIEW', 'pr-3')).rejects.toBeInstanceOf(BadRequestException);
      expect(reviews.find((r) => r.id === 'pr-3')!.status).toBe('PENDING');
    });

    it('16. neither action writes punch evidence, attendance, payroll or leave', async () => {
      const { service, prisma, forbiddenWrites } = standardRig();
      await service.decide({ id: 'hr', isHR: true }, 'PUNCH_EVIDENCE_REVIEW', 'pr-1', { action: 'MARK_REVIEWED' });
      await service.decide({ id: 'hr', isHR: true }, 'PUNCH_EVIDENCE_REVIEW', 'pr-3', { action: 'DISMISS', reason: 'Duplicate' });
      expect(forbiddenWrites).toEqual([]);
      for (const model of ['attendanceRegularization', 'leaveRequest']) {
        expect(Object.keys(prisma[model]).filter((m) => m !== 'findMany')).toEqual([]);
      }
      expect(prisma.punchEvidenceReview.updateMany.mock.calls.every(([args]: any) =>
        Object.keys(args.data).sort().join() === 'note,reviewedAt,reviewedById,status')).toBe(true);
    });
  });

  describe('RBAC', () => {
    it('17. only HR, Admin and Super Admin may list or act on system alerts', async () => {
      for (const id of ['hr', 'admin', 'super']) {
        const { service } = standardRig();
        await expect(service.list({ id }, 'company', 'system')).resolves.toMatchObject({ origin: 'system' });
      }
      for (const id of ['manager', 'employee']) {
        const { service, reviews } = standardRig();
        await expect(service.list({ id }, 'company', 'system')).rejects.toBeInstanceOf(ForbiddenException);
        await expect(service.list({ id }, 'team', 'system')).rejects.toBeInstanceOf(ForbiddenException);
        await expect(service.decide({ id, role: ACTORS[id].role }, 'PUNCH_EVIDENCE_REVIEW', 'pr-3', { action: 'MARK_REVIEWED' }))
          .rejects.toBeInstanceOf(ForbiddenException);
        expect(reviews.find((r) => r.id === 'pr-3')!.status).toBe('PENDING');
        expect((await service.counts({ id })).system).toBe(0);
      }
    });

    it('a manager still sees their team requests, and no system alert, on the default list', async () => {
      const { service } = standardRig();
      const { items } = await service.list({ id: 'manager' }, 'team');
      expect(items.map((i) => i.id).sort()).toEqual(['c-1', 'l-1']);
    });
  });
});
